 19→/**
 20→ * Binary serializer for {@link JlsmDocument} values.
 21→ *
 22→ * <p>
 23→ * The binary format consists of a header (schema version, field count, null bitmask, optional
 24→ * boolean bitmask) followed by serialized non-null, non-boolean field values in schema order.
 25→ *
 26→ * <p>
 27→ * Schema versioning: the header stores the write-time field count. On deserialization with a newer
 28→ * schema, only the write-time fields are decoded; additional fields in the current schema are left
 29→ * {@code null}.
 30→ *
 31→ * <p>
 32→ * Contiguous numeric arrays (INT32, INT64, FLOAT32, FLOAT64) use SIMD byte-swap acceleration via
 33→ * {@code jdk.incubator.vector}.
 34→ */
 35→public final class DocumentSerializer {
 36→
 37→    private DocumentSerializer() {
 38→    }
 39→
 40→    /**
 41→     * Returns a {@link MemorySerializer} for {@link JlsmDocument} values conforming to the given
 42→     * schema.
 43→     *
 44→     * @param schema the schema describing the document structure; must not be null
 45→     * @return a MemorySerializer for JlsmDocument
 46→     */
 47→    public static MemorySerializer<JlsmDocument> forSchema(JlsmSchema schema) {
 48→        Objects.requireNonNull(schema, "schema must not be null");
 49→        return new SchemaSerializer(schema);
 50→    }
 51→
 52→    // =========================================================================
 53→    // Implementation
 54→    // =========================================================================
 55→
 56→    /** SIMD species for byte-level operations (used for byte-swap shuffles). */
 57→    private static final VectorSpecies<Byte> BYTE_SPECIES = ByteVector.SPECIES_PREFERRED;
 58→
 59→    /** Byte-swap shuffle for INT32 / FLOAT32 (4-byte elements). */
 60→    private static final VectorShuffle<Byte> BSWAP32;
 61→
 62→    /** Byte-swap shuffle for INT64 / FLOAT64 (8-byte elements). */
 63→    private static final VectorShuffle<Byte> BSWAP64;
 64→
 65→    static {
 66→        final int byteLen = BYTE_SPECIES.length();
 67→        final int[] idx32 = new int[byteLen];
 68→        final int[] idx64 = new int[byteLen];
 69→        for (int i = 0; i + 3 < byteLen; i += 4) {
 70→            idx32[i + 0] = i + 3;
 71→            idx32[i + 1] = i + 2;
 72→            idx32[i + 2] = i + 1;
 73→            idx32[i + 3] = i + 0;
 74→        }
 75→        for (int i = 0; i + 7 < byteLen; i += 8) {
 76→            idx64[i + 0] = i + 7;
 77→            idx64[i + 1] = i + 6;
 78→            idx64[i + 2] = i + 5;
 79→            idx64[i + 3] = i + 4;
 80→            idx64[i + 4] = i + 3;
 81→            idx64[i + 5] = i + 2;
 82→            idx64[i + 6] = i + 1;
 83→            idx64[i + 7] = i + 0;
 84→        }
 85→        BSWAP32 = VectorShuffle.fromArray(BYTE_SPECIES, idx32, 0);
 86→        BSWAP64 = VectorShuffle.fromArray(BYTE_SPECIES, idx64, 0);
 87→    }
 88→
 89→    // -------------------------------------------------------------------------
 90→    // Serializer implementation
 91→    // -------------------------------------------------------------------------
 92→
 93→    /** Decodes a single non-boolean, non-null field from a byte array at the cursor position. */
 94→    @FunctionalInterface
 95→    private interface FieldDecoder {
 96→        Object decode(byte[] buf, Cursor cursor);
 97→    }
 98→
 99→    private static final class SchemaSerializer implements MemorySerializer<JlsmDocument> {
100→
101→        private final JlsmSchema schema;
102→        private final FieldDefinition[] fieldArray;
103→        private final boolean[] isBoolField;
104→        private final int[] prefixBoolCount;
105→        private final int fieldCount;
106→        private final int boolCount;
107→        private final int nullMaskBytes;
108→        private final int boolMaskBytes;
109→        private final FieldDecoder[] decoders;
110→
111→        SchemaSerializer(JlsmSchema schema) {
112→            this.schema = schema;
113→
114→            final List<FieldDefinition> fields = schema.fields();
115→            this.fieldCount = fields.size();
116→            this.fieldArray = fields.toArray(new FieldDefinition[0]);
117→
118→            // Precompute boolean field flags and prefix counts
119→            this.isBoolField = new boolean[fieldCount];
120→            this.prefixBoolCount = new int[fieldCount + 1];
121→            int bools = 0;
122→            for (int i = 0; i < fieldCount; i++) {
123→                prefixBoolCount[i] = bools;
124→                if (fieldArray[i].type() == FieldType.Primitive.BOOLEAN) {
125→                    isBoolField[i] = true;
126→                    bools++;
127→                }
128→            }
129→            prefixBoolCount[fieldCount] = bools;
130→            this.boolCount = bools;
131→
132→            this.nullMaskBytes = (fieldCount + 7) / 8;
133→            this.boolMaskBytes = boolCount > 0 ? (boolCount + 7) / 8 : 0;
134→
135→            // Build dispatch table for non-boolean field decoders
136→            this.decoders = new FieldDecoder[fieldCount];
137→            for (int i = 0; i < fieldCount; i++) {
138→                if (!isBoolField[i]) {
139→                    final FieldType type = fieldArray[i].type();
140→                    decoders[i] = (buf, cursor) -> decodeField(buf, cursor, type);
141→                }
142→            }
143→        }
144→
145→        @Override
146→        public MemorySegment serialize(JlsmDocument doc) {
147→            Objects.requireNonNull(doc, "doc must not be null");
148→            assert doc.schema() == schema || doc.schema().name().equals(schema.name())
149→                    : "document schema mismatch";
150→
151→            final List<FieldDefinition> fields = schema.fields();
152→            final int fieldCount = fields.size();
153→            final Object[] values = doc.values();
154→
155→            // Count boolean fields
156→            final int boolCount = countBoolFields(fields);
157→
158→            // Header size: 2 (version) + 2 (fieldCount) + ceil(fieldCount/8) (null mask)
159→            // + (boolCount > 0 ? ceil(boolCount/8) : 0) (bool mask)
160→            final int nullMaskBytes = (fieldCount + 7) / 8;
161→            final int boolMaskBytes = boolCount > 0 ? (boolCount + 7) / 8 : 0;
162→            final int headerSize = 2 + 2 + nullMaskBytes + boolMaskBytes;
163→
164→            // Two-pass: measure then encode
165→            final int payloadSize = measureFields(fields, values);
166→            final int totalSize = headerSize + payloadSize;
167→
168→            final byte[] buf = new byte[totalSize];
169→
170→            // Write header
171→            writeShortBE(buf, 0, (short) schema.version());
172→            writeShortBE(buf, 2, (short) fieldCount);
173→            // Null bitmask
174→            buildNullMask(fields, values, buf, 4);
175→            // Boolean bitmask
176→            if (boolCount > 0) {
177→                buildBoolMask(fields, values, buf, 4 + nullMaskBytes);
178→            }
179→
180→            // Write values
181→            final Cursor cursor = new Cursor(buf, headerSize);
182→            encodeFields(fields, values, cursor);
183→
184→            assert cursor.pos == totalSize : "cursor.pos should equal totalSize";
185→            return MemorySegment.ofArray(buf);
186→        }
187→
188→        @Override
189→        public JlsmDocument deserialize(MemorySegment segment) {
190→            Objects.requireNonNull(segment, "segment must not be null");
191→
192→            final ByteArrayView view = extractBytes(segment);
193→            final byte[] buf = view.data();
194→            final Cursor cursor = new Cursor(buf, view.offset());
195→
196→            // Read header
197→            final int _ = readShortBE(buf, cursor.advance(2)) & 0xFFFF;
198→            final int writeFieldCount = readShortBE(buf, cursor.advance(2)) & 0xFFFF;
199→
200→            // We only read min(writeFieldCount, currentFieldCount) fields
201→            final int readCount = Math.min(writeFieldCount, fieldCount);
202→
203→            // Use precomputed prefixBoolCount for O(1) lookup instead of O(n) iteration
204→            final int writeBoolCount = prefixBoolCount[readCount];
205→            final int writeNullMaskBytes = (writeFieldCount + 7) / 8;
206→            final int writeBoolMaskBytes = writeBoolCount > 0 ? (writeBoolCount + 7) / 8 : 0;
207→
208→            final int nullMaskOffset = cursor.advance(writeNullMaskBytes);
209→            final int boolMaskOffset = writeBoolCount > 0 ? cursor.advance(writeBoolMaskBytes) : -1;
210→
211→            // Decode values
212→            final Object[] values = new Object[fieldCount];
213→            // Fields beyond readCount remain null (new fields added in a later schema version)
214→
215→            int boolIdx = 0;
216→            for (int i = 0; i < readCount; i++) {
217→                final boolean isNull = isNullBit(buf, nullMaskOffset, i);
218→                if (isNull) {
219→                    if (isBoolField[i]) {
220→                        boolIdx++;
221→                    }
222→                    continue;
223→                }
224→                if (isBoolField[i]) {
225→                    assert boolMaskOffset >= 0 : "bool bitmask offset should be set";
226→                    values[i] = isBoolBit(buf, boolMaskOffset, boolIdx);
227→                    boolIdx++;
228→                } else {
229→                    values[i] = decoders[i].decode(buf, cursor);
230→                }
231→            }
232→
233→            return new JlsmDocument(schema, values);
234→        }
235→    }
236→
237→    // =========================================================================
238→    // Measure helpers (first pass)
239→    // =========================================================================
240→
241→    private static int measureFields(List<FieldDefinition> fields, Object[] values) {
242→        int total = 0;
243→        for (int i = 0; i < fields.size(); i++) {
244→            final FieldDefinition fd = fields.get(i);
245→            final Object val = values[i];
246→            if (val == null) {
247→                continue; // null → no value bytes
248→            }
249→            total += measureField(fd.type(), val);
250→        }
251→        return total;
252→    }
253→
254→    private static int measureField(FieldType type, Object value) {
255→        return switch (type) {
256→            case FieldType.Primitive p -> switch (p) {
257→                case STRING -> {
258→                    final byte[] utf8 = ((String) value).getBytes(StandardCharsets.UTF_8);
259→                    yield varIntSize(utf8.length) + utf8.length;
260→                }
261→                case INT8 -> 1;
262→                case INT16 -> 2;
263→                case INT32 -> 4;
264→                case INT64 -> 8;
265→                case FLOAT16 -> 2;
266→                case FLOAT32 -> 4;
267→                case FLOAT64 -> 8;
268→                case BOOLEAN -> 0; // packed in bitmask
269→                case TIMESTAMP -> 8;
270→            };
271→            case FieldType.ArrayType at -> {
272→                final Object[] arr = (Object[]) value;
273→                int sz = varIntSize(arr.length);
274→                for (Object elem : arr) {
275→                    sz += (elem == null) ? 0 : measureField(at.elementType(), elem);
276→                }
277→                yield sz;
278→            }
279→            case FieldType.VectorType vt -> {
280→                final int elemBytes = vt.elementType() == FieldType.Primitive.FLOAT32 ? 4 : 2;
281→                yield vt.dimensions() * elemBytes;
282→            }
283→            case FieldType.ObjectType ot -> {
284→                final JlsmDocument sub = (JlsmDocument) value;
285→                final List<FieldDefinition> subFields = ot.fields();
286→                final int subBoolCount = countBoolFields(subFields);
287→                final int subNullBytes = (subFields.size() + 7) / 8;
288→                final int subBoolBytes = subBoolCount > 0 ? (subBoolCount + 7) / 8 : 0;
289→                int sz = subNullBytes + subBoolBytes;
290→                sz += measureFields(subFields, sub.values());
291→                yield sz;
292→            }
293→        };
294→    }
295→
296→    // =========================================================================
297→    // Encode helpers (second pass)
298→    // =========================================================================
299→
300→    private static void encodeFields(List<FieldDefinition> fields, Object[] values, Cursor c) {
301→        for (int i = 0; i < fields.size(); i++) {
302→            final Object val = values[i];
303→            if (val == null) {
304→                continue;
305→            }
306→            encodeField(c, fields.get(i).type(), val);
307→        }
308→    }
