310→    private static void encodeField(Cursor c, FieldType type, Object value) {
311→        switch (type) {
312→            case FieldType.Primitive p -> {
313→                switch (p) {
314→                    case STRING -> {
315→                        final byte[] utf8 = ((String) value).getBytes(StandardCharsets.UTF_8);
316→                        writeVarInt(c, utf8.length);
317→                        System.arraycopy(utf8, 0, c.buf, c.pos, utf8.length);
318→                        c.pos += utf8.length;
319→                    }
320→                    case INT8 -> c.buf[c.pos++] = (Byte) value;
321→                    case INT16 -> {
322→                        writeShortBE(c.buf, c.pos, (Short) value);
323→                        c.pos += 2;
324→                    }
325→                    case INT32 -> {
326→                        writeIntBE(c.buf, c.pos, (Integer) value);
327→                        c.pos += 4;
328→                    }
329→                    case INT64 -> {
330→                        writeLongBE(c.buf, c.pos, (Long) value);
331→                        c.pos += 8;
332→                    }
333→                    case FLOAT16 -> {
334→                        writeShortBE(c.buf, c.pos, (Short) value);
335→                        c.pos += 2;
336→                    }
337→                    case FLOAT32 -> {
338→                        writeIntBE(c.buf, c.pos, Float.floatToRawIntBits((Float) value));
339→                        c.pos += 4;
340→                    }
341→                    case FLOAT64 -> {
342→                        writeLongBE(c.buf, c.pos, Double.doubleToRawLongBits((Double) value));
343→                        c.pos += 8;
344→                    }
345→                    case BOOLEAN -> {
346→                        // Boolean values are packed in the bool bitmask; nothing here
347→                    }
348→                    case TIMESTAMP -> {
349→                        writeLongBE(c.buf, c.pos, (Long) value);
350→                        c.pos += 8;
351→                    }
352→                }
353→            }
354→            case FieldType.ArrayType at -> encodeArray(c, at.elementType(), (Object[]) value);
355→            case FieldType.VectorType vt -> encodeVector(c, vt, value);
356→            case FieldType.ObjectType ot -> encodeObject(c, ot, (JlsmDocument) value);
357→        }
358→    }
359→
360→    private static void encodeArray(Cursor c, FieldType elemType, Object[] arr) {
361→        writeVarInt(c, arr.length);
362→        // SIMD-accelerated paths for contiguous numeric types
363→        if (elemType == FieldType.Primitive.INT32) {
364→            encodeInt32Array(c, arr);
365→        } else if (elemType == FieldType.Primitive.INT64) {
366→            encodeInt64Array(c, arr);
367→        } else if (elemType == FieldType.Primitive.FLOAT32) {
368→            encodeFloat32Array(c, arr);
369→        } else if (elemType == FieldType.Primitive.FLOAT64) {
370→            encodeFloat64Array(c, arr);
371→        } else {
372→            for (Object elem : arr) {
373→                if (elem != null) {
374→                    encodeField(c, elemType, elem);
375→                }
376→            }
377→        }
378→    }
379→
380→    private static void encodeVector(Cursor c, FieldType.VectorType vt, Object value) {
381→        final int d = vt.dimensions();
382→        if (vt.elementType() == FieldType.Primitive.FLOAT32) {
383→            final float[] vec = (float[]) value;
384→            assert vec.length == d : "vector length must match dimensions";
385→            for (int i = 0; i < d; i++) {
386→                writeIntBE(c.buf, c.pos, Float.floatToRawIntBits(vec[i]));
387→                c.pos += 4;
388→            }
389→        } else {
390→            // FLOAT16 — stored as short[]
391→            final short[] vec = (short[]) value;
392→            assert vec.length == d : "vector length must match dimensions";
393→            for (int i = 0; i < d; i++) {
394→                writeShortBE(c.buf, c.pos, vec[i]);
395→                c.pos += 2;
396→            }
397→        }
398→    }
399→
400→    private static void encodeObject(Cursor c, FieldType.ObjectType ot, JlsmDocument sub) {
401→        final List<FieldDefinition> subFields = ot.fields();
402→        final Object[] subValues = sub.values();
403→        final int boolCount = countBoolFields(subFields);
404→        final int nullMaskBytes = (subFields.size() + 7) / 8;
405→        final int boolMaskBytes = boolCount > 0 ? (boolCount + 7) / 8 : 0;
406→
407→        final int nullMaskStart = c.pos;
408→        c.pos += nullMaskBytes;
409→        final int boolMaskStart = boolCount > 0 ? c.pos : -1;
410→        if (boolCount > 0) {
411→            c.pos += boolMaskBytes;
412→        }
413→
414→        buildNullMask(subFields, subValues, c.buf, nullMaskStart);
415→        if (boolCount > 0) {
416→            buildBoolMask(subFields, subValues, c.buf, boolMaskStart);
417→        }
418→        encodeFields(subFields, subValues, c);
419→    }
