421→    // =========================================================================
422→    // SIMD encode paths
423→    // =========================================================================
424→
425→    private static void encodeInt32Array(Cursor c, Object[] arr) {
426→        final int simdLen = BYTE_SPECIES.length(); // bytes per SIMD register
427→        // Only use SIMD if we have enough data (at least one full vector worth of 4-byte ints)
428→        final int simdElems = simdLen / 4; // number of int32 elements per SIMD operation
429→        int i = 0;
430→        if (arr.length >= simdElems && simdLen >= 4) {
431→            final int[] ints = new int[simdElems];
432→            while (i + simdElems <= arr.length) {
433→                for (int j = 0; j < simdElems; j++) {
434→                    ints[j] = (Integer) arr[i + j];
435→                }
436→                // Load as bytes (little-endian native), swap to big-endian
437→                final ByteVector bv = IntVector.fromArray(IntVector.SPECIES_PREFERRED, ints, 0)
438→                        .reinterpretAsBytes();
439→                bv.rearrange(BSWAP32).intoArray(c.buf, c.pos);
440→                c.pos += simdLen;
441→                i += simdElems;
442→            }
443→        }
444→        // Scalar remainder
445→        while (i < arr.length) {
446→            writeIntBE(c.buf, c.pos, (Integer) arr[i++]);
447→            c.pos += 4;
448→        }
449→    }
450→
451→    private static void encodeInt64Array(Cursor c, Object[] arr) {
452→        final int simdLen = BYTE_SPECIES.length();
453→        final int simdElems = simdLen / 8;
454→        int i = 0;
455→        if (arr.length >= simdElems && simdLen >= 8) {
456→            final long[] longs = new long[simdElems];
457→            while (i + simdElems <= arr.length) {
458→                for (int j = 0; j < simdElems; j++) {
459→                    longs[j] = (Long) arr[i + j];
460→                }
461→                final ByteVector bv = LongVector.fromArray(LongVector.SPECIES_PREFERRED, longs, 0)
462→                        .reinterpretAsBytes();
463→                bv.rearrange(BSWAP64).intoArray(c.buf, c.pos);
464→                c.pos += simdLen;
465→                i += simdElems;
466→            }
467→        }
468→        while (i < arr.length) {
469→            writeLongBE(c.buf, c.pos, (Long) arr[i++]);
470→            c.pos += 8;
471→        }
472→    }
473→
474→    private static void encodeFloat32Array(Cursor c, Object[] arr) {
475→        final int simdLen = BYTE_SPECIES.length();
476→        final int simdElems = simdLen / 4;
477→        int i = 0;
478→        if (arr.length >= simdElems && simdLen >= 4) {
479→            final float[] floats = new float[simdElems];
480→            while (i + simdElems <= arr.length) {
481→                for (int j = 0; j < simdElems; j++) {
482→                    floats[j] = (Float) arr[i + j];
483→                }
484→                final ByteVector bv = FloatVector
485→                        .fromArray(FloatVector.SPECIES_PREFERRED, floats, 0).reinterpretAsBytes();
486→                bv.rearrange(BSWAP32).intoArray(c.buf, c.pos);
487→                c.pos += simdLen;
488→                i += simdElems;
489→            }
490→        }
491→        while (i < arr.length) {
492→            writeIntBE(c.buf, c.pos, Float.floatToRawIntBits((Float) arr[i++]));
493→            c.pos += 4;
494→        }
495→    }
496→
497→    private static void encodeFloat64Array(Cursor c, Object[] arr) {
498→        final int simdLen = BYTE_SPECIES.length();
499→        final int simdElems = simdLen / 8;
500→        int i = 0;
501→        if (arr.length >= simdElems && simdLen >= 8) {
502→            final double[] doubles = new double[simdElems];
503→            while (i + simdElems <= arr.length) {
504→                for (int j = 0; j < simdElems; j++) {
505→                    doubles[j] = (Double) arr[i + j];
506→                }
507→                final ByteVector bv = DoubleVector
508→                        .fromArray(DoubleVector.SPECIES_PREFERRED, doubles, 0).reinterpretAsBytes();
509→                bv.rearrange(BSWAP64).intoArray(c.buf, c.pos);
510→                c.pos += simdLen;
511→                i += simdElems;
512→            }
513→        }
514→        while (i < arr.length) {
515→            writeLongBE(c.buf, c.pos, Double.doubleToRawLongBits((Double) arr[i++]));
516→            c.pos += 8;
517→        }
518→    }
519→
520→    // =========================================================================
521→    // Decode helpers
522→    // =========================================================================
523→
524→    private static Object decodeField(byte[] buf, Cursor cursor, FieldType type) {
525→        return switch (type) {
526→            case FieldType.Primitive p -> switch (p) {
527→                case STRING -> {
528→                    final int len = readVarInt(buf, cursor);
529→                    final String s = new String(buf, cursor.pos, len, StandardCharsets.UTF_8);
530→                    cursor.pos += len;
531→                    yield s;
532→                }
533→                case INT8 -> buf[cursor.pos++];
534→                case INT16 -> {
535→                    final short v = readShortBE(buf, cursor.pos);
536→                    cursor.pos += 2;
537→                    yield v;
538→                }
539→                case INT32 -> {
540→                    final int v = readIntBE(buf, cursor.pos);
541→                    cursor.pos += 4;
542→                    yield v;
543→                }
544→                case INT64 -> {
545→                    final long v = readLongBE(buf, cursor.pos);
546→                    cursor.pos += 8;
547→                    yield v;
548→                }
549→                case FLOAT16 -> {
550→                    final short v = readShortBE(buf, cursor.pos);
551→                    cursor.pos += 2;
552→                    yield v;
553→                }
554→                case FLOAT32 -> {
555→                    final float v = Float.intBitsToFloat(readIntBE(buf, cursor.pos));
556→                    cursor.pos += 4;
557→                    yield v;
558→                }
559→                case FLOAT64 -> {
560→                    final double v = Double.longBitsToDouble(readLongBE(buf, cursor.pos));
561→                    cursor.pos += 8;
562→                    yield v;
563→                }
564→                case BOOLEAN ->
565→                    throw new AssertionError("BOOLEAN should be handled via bool bitmask");
566→                case TIMESTAMP -> {
567→                    final long v = readLongBE(buf, cursor.pos);
568→                    cursor.pos += 8;
569→                    yield v;
570→                }
571→            };
572→            case FieldType.ArrayType at -> decodeArray(buf, cursor, at);
573→            case FieldType.VectorType vt -> decodeVector(buf, cursor, vt);
574→            case FieldType.ObjectType ot -> decodeObject(buf, cursor, ot);
575→        };
576→    }
577→
578→    private static Object[] decodeArray(byte[] buf, Cursor cursor, FieldType.ArrayType at) {
579→        final int count = readVarInt(buf, cursor);
580→        // SIMD-accelerated decode for contiguous numeric types
581→        final FieldType elemType = at.elementType();
582→        if (elemType == FieldType.Primitive.INT32) {
583→            return decodeInt32Array(buf, cursor, count);
584→        } else if (elemType == FieldType.Primitive.INT64) {
585→            return decodeInt64Array(buf, cursor, count);
586→        } else if (elemType == FieldType.Primitive.FLOAT32) {
587→            return decodeFloat32Array(buf, cursor, count);
588→        } else if (elemType == FieldType.Primitive.FLOAT64) {
589→            return decodeFloat64Array(buf, cursor, count);
590→        }
591→        final Object[] arr = new Object[count];
592→        for (int i = 0; i < count; i++) {
593→            arr[i] = decodeField(buf, cursor, elemType);
594→        }
595→        return arr;
596→    }
597→
598→    private static Object decodeVector(byte[] buf, Cursor cursor, FieldType.VectorType vt) {
599→        final int d = vt.dimensions();
600→        if (vt.elementType() == FieldType.Primitive.FLOAT32) {
601→            final float[] vec = new float[d];
602→            for (int i = 0; i < d; i++) {
603→                vec[i] = Float.intBitsToFloat(readIntBE(buf, cursor.pos));
604→                cursor.pos += 4;
605→            }
606→            return vec;
607→        } else {
608→            // FLOAT16 — return as short[]
609→            final short[] vec = new short[d];
610→            for (int i = 0; i < d; i++) {
611→                vec[i] = readShortBE(buf, cursor.pos);
612→                cursor.pos += 2;
613→            }
614→            return vec;
615→        }
616→    }
617→
618→    private static Object decodeObject(byte[] buf, Cursor cursor, FieldType.ObjectType ot) {
619→        final List<FieldDefinition> subFields = ot.fields();
620→        final int subFieldCount = subFields.size();
621→        final int subBoolCount = countBoolFields(subFields);
622→        final int nullMaskBytes = (subFieldCount + 7) / 8;
623→        final int boolMaskBytes = subBoolCount > 0 ? (subBoolCount + 7) / 8 : 0;
624→
625→        final int nullMaskOffset = cursor.advance(nullMaskBytes);
626→        final int boolMaskOffset = subBoolCount > 0 ? cursor.advance(boolMaskBytes) : -1;
627→
628→        final Object[] subValues = new Object[subFieldCount];
629→        int boolIdx = 0;
630→        for (int i = 0; i < subFieldCount; i++) {
631→            final FieldDefinition fd = subFields.get(i);
632→            final boolean isNull = isNullBit(buf, nullMaskOffset, i);
633→            if (isNull) {
634→                if (fd.type() == FieldType.Primitive.BOOLEAN) {
635→                    boolIdx++;
636→                }
637→                subValues[i] = null;
638→                continue;
639→            }
640→            if (fd.type() == FieldType.Primitive.BOOLEAN) {
641→                assert boolMaskOffset >= 0 : "bool bitmask offset should be set";
642→                subValues[i] = isBoolBit(buf, boolMaskOffset, boolIdx);
643→                boolIdx++;
644→            } else {
645→                subValues[i] = decodeField(buf, cursor, fd.type());
646→            }
647→        }
648→
649→        // Synthesize a schema for the sub-document
650→        final JlsmSchema subSchema = ot.toSchema("nested", 0);
651→        return new JlsmDocument(subSchema, subValues);
652→    }
653→
654→    // =========================================================================
655→    // SIMD decode paths
656→    // =========================================================================
657→
658→    private static Object[] decodeInt32Array(byte[] buf, Cursor cursor, int count) {
659→        final Object[] result = new Object[count];
660→        final int simdLen = BYTE_SPECIES.length();
661→        final int simdElems = simdLen / 4;
662→        final int[] tmp = new int[simdElems];
663→        int i = 0;
664→        if (count >= simdElems && simdLen >= 4) {
665→            while (i + simdElems <= count) {
666→                ByteVector.fromArray(BYTE_SPECIES, buf, cursor.pos).rearrange(BSWAP32)
667→                        .reinterpretAsInts().intoArray(tmp, 0);
668→                for (int j = 0; j < simdElems; j++) {
669→                    result[i + j] = tmp[j];
670→                }
671→                cursor.pos += simdLen;
672→                i += simdElems;
673→            }
674→        }
675→        while (i < count) {
676→            result[i++] = readIntBE(buf, cursor.pos);
677→            cursor.pos += 4;
678→        }
679→        return result;
680→    }
681→
682→    private static Object[] decodeInt64Array(byte[] buf, Cursor cursor, int count) {
683→        final Object[] result = new Object[count];
684→        final int simdLen = BYTE_SPECIES.length();
685→        final int simdElems = simdLen / 8;
686→        final long[] tmp = new long[simdElems];
687→        int i = 0;
688→        if (count >= simdElems && simdLen >= 8) {
689→            while (i + simdElems <= count) {
690→                ByteVector.fromArray(BYTE_SPECIES, buf, cursor.pos).rearrange(BSWAP64)
691→                        .reinterpretAsLongs().intoArray(tmp, 0);
692→                for (int j = 0; j < simdElems; j++) {
693→                    result[i + j] = tmp[j];
694→                }
695→                cursor.pos += simdLen;
696→                i += simdElems;
697→            }
698→        }
699→        while (i < count) {
700→            result[i++] = readLongBE(buf, cursor.pos);
701→            cursor.pos += 8;
702→        }
703→        return result;
704→    }
705→
706→    private static Object[] decodeFloat32Array(byte[] buf, Cursor cursor, int count) {
707→        final Object[] result = new Object[count];
708→        final int simdLen = BYTE_SPECIES.length();
709→        final int simdElems = simdLen / 4;
710→        final float[] tmp = new float[simdElems];
711→        int i = 0;
712→        if (count >= simdElems && simdLen >= 4) {
713→            while (i + simdElems <= count) {
714→                ByteVector.fromArray(BYTE_SPECIES, buf, cursor.pos).rearrange(BSWAP32)
715→                        .reinterpretAsFloats().intoArray(tmp, 0);
716→                for (int j = 0; j < simdElems; j++) {
717→                    result[i + j] = tmp[j];
718→                }
719→                cursor.pos += simdLen;
720→                i += simdElems;
721→            }
722→        }
723→        while (i < count) {
724→            result[i++] = Float.intBitsToFloat(readIntBE(buf, cursor.pos));
725→            cursor.pos += 4;
726→        }
727→        return result;
728→    }
729→
730→    private static Object[] decodeFloat64Array(byte[] buf, Cursor cursor, int count) {
731→        final Object[] result = new Object[count];
732→        final int simdLen = BYTE_SPECIES.length();
733→        final int simdElems = simdLen / 8;
734→        final double[] tmp = new double[simdElems];
735→        int i = 0;
736→        if (count >= simdElems && simdLen >= 8) {
737→            while (i + simdElems <= count) {
738→                ByteVector.fromArray(BYTE_SPECIES, buf, cursor.pos).rearrange(BSWAP64)
739→                        .reinterpretAsDoubles().intoArray(tmp, 0);
740→                for (int j = 0; j < simdElems; j++) {
741→                    result[i + j] = tmp[j];
742→                }
743→                cursor.pos += simdLen;
744→                i += simdElems;
745→            }
746→        }
747→        while (i < count) {
748→            result[i++] = Double.longBitsToDouble(readLongBE(buf, cursor.pos));
749→            cursor.pos += 8;
750→        }
751→        return result;
752→    }
753→
754→    // =========================================================================
755→    // Bitmask helpers
756→    // =========================================================================
757→
758→    private static void buildNullMask(List<FieldDefinition> fields, Object[] values, byte[] buf,
759→            int offset) {
760→        for (int i = 0; i < fields.size(); i++) {
761→            if (values[i] == null) {
762→                buf[offset + i / 8] |= (byte) (1 << (i % 8));
763→            }
764→        }
765→    }
766→
767→    private static void buildBoolMask(List<FieldDefinition> fields, Object[] values, byte[] buf,
768→            int offset) {
769→        int boolIdx = 0;
770→        for (int i = 0; i < fields.size(); i++) {
771→            if (fields.get(i).type() == FieldType.Primitive.BOOLEAN) {
772→                final Object val = values[i];
773→                if (val instanceof Boolean b && b) {
774→                    buf[offset + boolIdx / 8] |= (byte) (1 << (boolIdx % 8));
775→                }
776→                boolIdx++;
777→            }
778→        }
779→    }
780→
781→    private static boolean isNullBit(byte[] buf, int maskOffset, int fieldIndex) {
782→        return (buf[maskOffset + fieldIndex / 8] & (1 << (fieldIndex % 8))) != 0;
783→    }
784→
785→    private static boolean isBoolBit(byte[] buf, int maskOffset, int boolIndex) {
786→        return (buf[maskOffset + boolIndex / 8] & (1 << (boolIndex % 8))) != 0;
787→    }
788→
789→    private static int countBoolFields(List<FieldDefinition> fields) {
790→        int count = 0;
791→        for (final FieldDefinition fd : fields) {
792→            if (fd.type() == FieldType.Primitive.BOOLEAN) {
793→                count++;
794→            }
795→        }
796→        return count;
797→    }
798→
799→    private static int countBoolFieldsUpTo(List<FieldDefinition> fields, int limit) {
800→        int count = 0;
801→        final int bound = Math.min(limit, fields.size());
802→        for (int i = 0; i < bound; i++) {
803→            if (fields.get(i).type() == FieldType.Primitive.BOOLEAN) {
804→                count++;
805→            }
806→        }
807→        return count;
808→    }
809→
810→    // =========================================================================
811→    // VarInt (LEB128 unsigned)
812→    // =========================================================================
813→
814→    private static int varIntSize(int value) {
815→        assert value >= 0 : "VarInt value must be non-negative";
816→        if (value < 128) {
817→            return 1;
818→        }
819→        if (value < 16384) {
820→            return 2;
821→        }
822→        if (value < 2097152) {
823→            return 3;
824→        }
825→        if (value < 268435456) {
826→            return 4;
827→        }
828→        return 5;
829→    }
830→
831→    private static void writeVarInt(Cursor c, int value) {
832→        assert value >= 0 : "VarInt value must be non-negative";
833→        while (true) {
834→            if ((value & ~0x7F) == 0) {
835→                c.buf[c.pos++] = (byte) value;
836→                return;
837→            }
838→            c.buf[c.pos++] = (byte) ((value & 0x7F) | 0x80);
839→            value >>>= 7;
840→        }
841→    }
842→
843→    private static int readVarInt(byte[] buf, Cursor cursor) {
844→        int result = 0;
845→        int shift = 0;
846→        while (true) {
847→            final byte b = buf[cursor.pos++];
848→            result |= (b & 0x7F) << shift;
849→            if ((b & 0x80) == 0) {
850→                break;
851→            }
852→            shift += 7;
853→            assert shift <= 35 : "VarInt overflow — corrupt data";
854→        }
855→        return result;
856→    }
857→
858→    // =========================================================================
859→    // Primitive I/O
860→    // =========================================================================
861→
862→    private static void writeShortBE(byte[] buf, int offset, short value) {
863→        buf[offset] = (byte) (value >> 8);
864→        buf[offset + 1] = (byte) value;
865→    }
866→
867→    private static short readShortBE(byte[] buf, int offset) {
868→        return (short) ((buf[offset] << 8) | (buf[offset + 1] & 0xFF));
869→    }
870→
871→    private static void writeIntBE(byte[] buf, int offset, int value) {
872→        buf[offset] = (byte) (value >> 24);
873→        buf[offset + 1] = (byte) (value >> 16);
874→        buf[offset + 2] = (byte) (value >> 8);
875→        buf[offset + 3] = (byte) value;
876→    }
877→
878→    private static int readIntBE(byte[] buf, int offset) {
879→        return ((buf[offset] & 0xFF) << 24) | ((buf[offset + 1] & 0xFF) << 16)
880→                | ((buf[offset + 2] & 0xFF) << 8) | (buf[offset + 3] & 0xFF);
881→    }
882→
883→    private static void writeLongBE(byte[] buf, int offset, long value) {
884→        buf[offset] = (byte) (value >> 56);
885→        buf[offset + 1] = (byte) (value >> 48);
886→        buf[offset + 2] = (byte) (value >> 40);
887→        buf[offset + 3] = (byte) (value >> 32);
888→        buf[offset + 4] = (byte) (value >> 24);
889→        buf[offset + 5] = (byte) (value >> 16);
890→        buf[offset + 6] = (byte) (value >> 8);
891→        buf[offset + 7] = (byte) value;
892→    }
893→
894→    private static long readLongBE(byte[] buf, int offset) {
895→        return ((long) (buf[offset] & 0xFF) << 56) | ((long) (buf[offset + 1] & 0xFF) << 48)
896→                | ((long) (buf[offset + 2] & 0xFF) << 40) | ((long) (buf[offset + 3] & 0xFF) << 32)
897→                | ((long) (buf[offset + 4] & 0xFF) << 24) | ((long) (buf[offset + 5] & 0xFF) << 16)
898→                | ((long) (buf[offset + 6] & 0xFF) << 8) | ((long) (buf[offset + 7] & 0xFF));
899→    }
900→
901→    // =========================================================================
902→    // Heap fast path
903→    // =========================================================================
904→
905→    /** View of a byte array with an offset — enables zero-copy for heap-backed segments. */
906→    private record ByteArrayView(byte[] data, int offset) {
907→    }
908→
909→    /**
910→     * Extracts a byte array view from a {@link MemorySegment}. For heap-backed segments (created
911→     * via {@code MemorySegment.ofArray(byte[])}), returns the backing array directly — zero-copy.
912→     * For off-heap or sliced segments, falls back to {@code toArray()}.
913→     */
914→    private static ByteArrayView extractBytes(MemorySegment segment) {
915→        Optional<Object> heapBase = segment.heapBase();
916→        if (heapBase.isPresent() && heapBase.get() instanceof byte[] data
917→                && segment.byteSize() == data.length) {
918→            // Full array — offset is 0 for MemorySegment.ofArray(byte[])
919→            return new ByteArrayView(data, 0);
920→        } else {
921→            byte[] data = segment.toArray(ValueLayout.JAVA_BYTE);
922→            return new ByteArrayView(data, 0);
923→        }
924→    }
925→
926→    // =========================================================================
927→    // Cursor
928→    // =========================================================================
929→
930→    /** Mutable position cursor for sequential byte-array I/O. */
931→    private static final class Cursor {
932→
933→        final byte[] buf;
934→        int pos;
935→
936→        Cursor(byte[] buf, int pos) {
937→            this.buf = buf;
938→            this.pos = pos;
939→        }
940→
941→        /** Advances position by {@code n} bytes and returns the old position. */
942→        int advance(int n) {
943→            final int old = pos;
944→            pos += n;
945→            return old;
946→        }
947→    }
948→}
