package jlsm.perf;

import jlsm.core.io.MemorySerializer;
import jlsm.table.DocumentSerializer;
import jlsm.table.FieldType;
import jlsm.table.JlsmDocument;
import jlsm.table.JlsmSchema;
import org.openjdk.jmh.annotations.*;

import java.lang.foreign.Arena;
import java.lang.foreign.MemorySegment;
import java.util.concurrent.TimeUnit;

/**
 * Scratch benchmark validating DocumentSerializer deserialization optimizations:
 * heap fast path (extractBytes), precomputed schema constants (prefixBoolCount),
 * and field decoder dispatch table.
 *
 * <p>Hypothesis: optimized deserialize() should show measurable throughput improvement
 * over the pre-optimization baseline (commit eef5903) where deserialization consumed
 * 34% of scan CPU with 103 samples in toArray copy.
 */
@BenchmarkMode(Mode.Throughput)
@OutputTimeUnit(TimeUnit.SECONDS)
@State(Scope.Benchmark)
public class DocumentDeserializeScratch {

    private static final JlsmSchema SCHEMA = JlsmSchema.builder("bench", 1)
            .field("name", FieldType.Primitive.STRING)
            .field("age", FieldType.Primitive.INT32)
            .field("active", FieldType.Primitive.BOOLEAN)
            .field("score", FieldType.Primitive.FLOAT64)
            .field("tag", FieldType.Primitive.STRING)
            .field("ts", FieldType.Primitive.TIMESTAMP)
            .field("flag2", FieldType.Primitive.BOOLEAN)
            .field("count", FieldType.Primitive.INT64)
            .build();

    private MemorySerializer<JlsmDocument> serializer;
    private MemorySegment heapSegment;
    private MemorySegment offHeapSegment;
    private Arena arena;

    @Setup(Level.Trial)
    public void setup() {
        serializer = DocumentSerializer.forSchema(SCHEMA);
        JlsmDocument doc = JlsmDocument.of(SCHEMA,
                "name", "Alice Wonderland",
                "age", 30,
                "active", true,
                "score", 98.765,
                "tag", "benchmark-test-value",
                "ts", 1710720000000L,
                "flag2", false,
                "count", 42_000_000L);

        heapSegment = serializer.serialize(doc);

        // Create off-heap copy for fallback path benchmark
        arena = Arena.ofShared();
        offHeapSegment = arena.allocate(heapSegment.byteSize());
        MemorySegment.copy(heapSegment, 0, offHeapSegment, 0, heapSegment.byteSize());
    }

    @TearDown(Level.Trial)
    public void teardown() {
        if (arena != null) {
            arena.close();
        }
    }

    /** Heap-backed segment — should use extractBytes zero-copy path. */
    @Benchmark
    public JlsmDocument deserializeHeap() {
        return serializer.deserialize(heapSegment);
    }

    /** Off-heap segment — falls back to toArray() copy. */
    @Benchmark
    public JlsmDocument deserializeOffHeap() {
        return serializer.deserialize(offHeapSegment);
    }
}

