 90→    /**
 91→     * Builder for {@link JlsmSchema}.
 92→     *
 93→     * <p>
 94→     * The builder tracks a current nesting depth; {@link #objectField} creates a nested builder at
 95→     * {@code depth + 1}. {@link #build()} validates that no level exceeds the configured
 96→     * {@code maxDepth}.
 97→     */
 98→    public static final class Builder {
 99→
100→        private final String name;
101→        private final int version;
102→        private final int currentDepth;
103→        private final List<FieldDefinition> fields = new ArrayList<>();
104→
105→        // maxDepth is tracked on the root builder; nested builders reference the root
106→        private int maxDepth;
107→        // parentBuilder is null for the root; non-null for nested builders
108→        private final Builder rootBuilder;
109→
110→        private Builder(String name, int version, int currentDepth, int maxDepth,
111→                Builder rootBuilder) {
112→            this.name = name;
113→            this.version = version;
114→            this.currentDepth = currentDepth;
115→            this.maxDepth = maxDepth;
116→            this.rootBuilder = rootBuilder;
117→        }
118→
119→        /**
120→         * Adds a primitive or array field to this schema level.
121→         *
122→         * @param name the field name; must not be null
123→         * @param type the field type; must not be null
124→         * @return this builder
125→         */
126→        public Builder field(String name, FieldType type) {
127→            Objects.requireNonNull(name, "name must not be null");
128→            Objects.requireNonNull(type, "type must not be null");
129→            assert name != null : "name must not be null";
130→            assert type != null : "type must not be null";
131→            fields.add(new FieldDefinition(name, type));
132→            return this;
133→        }
134→
135→        /**
136→         * Adds a vector field with the given element type and fixed dimensions.
137→         *
138→         * @param name the field name; must not be null
139→         * @param elementType the element precision; must be FLOAT16 or FLOAT32
140→         * @param dimensions the fixed number of elements per vector; must be positive
141→         * @return this builder
142→         */
143→        public Builder vectorField(String name, FieldType.Primitive elementType, int dimensions) {
144→            Objects.requireNonNull(name, "name must not be null");
145→            Objects.requireNonNull(elementType, "elementType must not be null");
146→            assert name != null : "name must not be null";
147→            assert elementType != null : "elementType must not be null";
148→            return field(name, FieldType.vector(elementType, dimensions));
149→        }
150→
151→        /**
152→         * Adds a nested object field by building its inner schema inline via a Consumer.
153→         *
154→         * <p>
155→         * The nested builder is passed to the consumer at {@code currentDepth + 1}. If the nested
156→         * depth exceeds maxDepth, {@link #build()} will throw.
157→         *
158→         * @param name the field name; must not be null
159→         * @param nested a consumer that populates the nested schema's builder; must not be null
160→         * @return this builder
161→         */
162→        public Builder objectField(String name, Consumer<Builder> nested) {
163→            Objects.requireNonNull(name, "name must not be null");
164→            Objects.requireNonNull(nested, "nested must not be null");
165→            assert name != null : "name must not be null";
166→            assert nested != null : "nested consumer must not be null";
167→
168→            final int nestedDepth = currentDepth + 1;
169→            final Builder root = (rootBuilder != null) ? rootBuilder : this;
170→            final Builder nestedBuilder = new Builder(name, version, nestedDepth, maxDepth, root);
171→            nested.accept(nestedBuilder);
172→
173→            // Build the nested ObjectType — validation happens here
174→            final List<FieldDefinition> nestedFields = nestedBuilder.buildFields(root.maxDepth);
175→            fields.add(new FieldDefinition(name, new FieldType.ObjectType(nestedFields)));
176→            return this;
177→        }
178→
179→        /**
180→         * Sets the maximum nesting depth allowed for object fields. Must be between 0 and 25
181→         * (inclusive).
182→         *
183→         * @param maxDepth the maximum depth
184→         * @return this builder
185→         * @throws IllegalArgumentException if {@code maxDepth} exceeds 25
186→         */
187→        public Builder maxDepth(int maxDepth) {
188→            if (maxDepth > ABSOLUTE_MAX_DEPTH) {
189→                throw new IllegalArgumentException("maxDepth " + maxDepth
190→                        + " exceeds absolute maximum of " + ABSOLUTE_MAX_DEPTH);
191→            }
192→            if (maxDepth < 0) {
193→                throw new IllegalArgumentException("maxDepth must not be negative");
194→            }
195→            this.maxDepth = maxDepth;
196→            return this;
197→        }
198→
199→        /**
200→         * Builds and returns the {@link JlsmSchema}.
201→         *
202→         * @return the constructed schema
203→         * @throws IllegalArgumentException if maxDepth exceeds 25 or if any field's nesting exceeds
204→         *             maxDepth
205→         */
206→        public JlsmSchema build() {
207→            if (maxDepth > ABSOLUTE_MAX_DEPTH) {
208→                throw new IllegalArgumentException("maxDepth " + maxDepth
209→                        + " exceeds absolute maximum of " + ABSOLUTE_MAX_DEPTH);
210→            }
211→            // Depth validation is already done eagerly in objectField → buildFields
212→            return new JlsmSchema(name, version, fields, maxDepth);
213→        }
214→
215→        /**
216→         * Internal helper: returns the fields accumulated by this builder, after validating that
217→         * {@code currentDepth <= allowedMaxDepth}.
218→         *
219→         * @param allowedMaxDepth the depth limit from the root builder
220→         * @return the list of field definitions
221→         * @throws IllegalArgumentException if this builder's depth exceeds allowedMaxDepth
222→         */
223→        private List<FieldDefinition> buildFields(int allowedMaxDepth) {
224→            if (currentDepth > allowedMaxDepth) {
225→                throw new IllegalArgumentException("Nested object depth " + currentDepth
226→                        + " exceeds maxDepth " + allowedMaxDepth);
227→            }
228→            return List.copyOf(fields);
229→        }
230→    }
