10→    private static JlsmDocument roundTrip(JlsmSchema schema, JlsmDocument doc) {
11→        MemorySerializer<JlsmDocument> ser = DocumentSerializer.forSchema(schema);
12→        MemorySegment bytes = ser.serialize(doc);
13→        return ser.deserialize(bytes);
