19→                .field("i8", FieldType.Primitive.INT8).field("i16", FieldType.Primitive.INT16)
20→                .field("i32", FieldType.Primitive.INT32).field("i64", FieldType.Primitive.INT64)
21→                .field("f32", FieldType.Primitive.FLOAT32).field("f64", FieldType.Primitive.FLOAT64)
22→                .field("bool", FieldType.Primitive.BOOLEAN)
23→                .field("ts", FieldType.Primitive.TIMESTAMP).build();
24→        JlsmDocument doc = JlsmDocument.of(schema, "s", "hello", "i8", (byte) 42, "i16",
25→                (short) 1000, "i32", 123456, "i64", 999999999999L, "f32", 3.14f, "f64", 2.718281828,
26→                "bool", true, "ts", 1700000000000L);
27→        JlsmDocument out = roundTrip(schema, doc);
28→        assertEquals("hello", out.getString("s"));
29→        assertEquals((byte) 42, out.getByte("i8"));
30→        assertEquals((short) 1000, out.getShort("i16"));
31→        assertEquals(123456, out.getInt("i32"));
32→        assertEquals(999999999999L, out.getLong("i64"));
